        onContentReady() {
            //3
            console.log("OnContentReady");       

            // flash se stavem knihy
            Eko.Utils.ShowEkoBookStateFlash(this, this.AktSubrady);

            //ukončeno v waitForValues
            this.beginOperation("Načítání detailu pokladního dokladu....")

            this.setBreadcrumbs([{ caption: Gordic.Eko.Detail.getDetailTitle("Pokladní doklad", this.model.ixp, this.model.ac,true), defaultAction: true }]);

            //všechny políčka na detailu
            const fields = this.findFields();

            //formulář není k editaci všechny políčka zablokuji
            //if (!this.isEditable)
            //    fields.gfield("option", "disabled", true);

            //zablokuji všechny políčka která nejsou nikdy editována
            fields.findFields(".js-notEditable").gfield("option", "disabled", true);

            if (this.model.ixs_esu == "0000SE00000M") this.model.ixs_esu = null;

            fields.findFields().gfield("model", "apply", this.model, { initialValues: true });
            fields.findFields().gfield("model", "validators", this.validators);

            this.findForms().gform("waitForValues")
                .always(() => {

                    this.doplnRecapDPH();

                    //  this.beginOperation("Načítání detailu pokladního dokladu...."
                    (this.recapDPH as Gordic.Gin.WebClient.recapDPH).refresh();
                    this.endOperation();

                   

             });

            this.setFormular();

            this.puvodniKtgTyp = this.model.ktg_typ;
        

            if (this.newPodani) {
                
                this.newPodani = false;
            }

            if (this.vyuctovaniZalohyPri) {
                this.VyuctovaniZalohy();
                this.vyuctovaniZalohyPri = false;

            }

            this.changePorizovac = false;


            //OPTIMALIZACE
            const kontaceZaokrouhleni = "9999999999999";

            //upozornění na to, že nejsou nastaveny kontace pro zaokrouhlovací položku,ale je zapnuto vytvoření haléřové zaokrouhlovaní
            if (this.pokParams.PokGenHalzao && (this.pokParams.PokGenHalkop == kontaceZaokrouhleni || this.pokParams.PokGenHalkov == kontaceZaokrouhleni)) //99999999 default hodnota porametru
                 this.notification("showToast", { id: "idZaokrouhleni", title: "Zaokrouhlovací položka", content : "Je nastaveno vytvoření zaokrouhlovací položky, ale nejsou vyplněny kódy kontace!" });

            //this.notification("showToast", { id: "idtest", title: "Zkouška", content: "Zkouška že jde použít toto oznámení a může se na něco hodit" });

            //STATUS BAR
            let eviStatus = Eko.Utils.RecordFormatType.Neprecteno;

            if (this.model.up_stav == Hpl.Interface.StavDokladu.schvaleno)
                eviStatus = Eko.Utils.RecordFormatType.Schvaleno;

            if (this.model.up_stav == Hpl.Interface.StavDokladu.zauctovano)
                eviStatus = Eko.Utils.RecordFormatType.Realizovano;

            Gordic.Eko.Detail.StatusBar.updateItem(
                this.statuses!["statusBarStavEvi"]!,
                this.model.up_stav_txt!.toUpperCase() + (this.model.aktivita == 900 ? "|ZRUŠENO" : ""),
                eviStatus
            );

            let fucStatus = Eko.Utils.RecordFormatType.Neprecteno;

            if (this.model.fuc_s_zau == 20)
                fucStatus = Eko.Utils.RecordFormatType.Realizovano;


            Gordic.Eko.Detail.StatusBar.updateItem(
                this.statuses!["statusBarStavFuc"]!,
                this.model.fuc_s_zau_txt == null ? "" : this.model.fuc_s_zau_txt.toUpperCase(),
                fucStatus
            );      

            let stornoStatus = Eko.Utils.RecordFormatType.Neprecteno;

            if (this.model.s_sto === Hpl.Interface.StavStorna.storno)
                stornoStatus = Eko.Utils.RecordFormatType.Stornovano;

            if (this.model.s_sto === Hpl.Interface.StavStorna.stornovaci)
                stornoStatus = Eko.Utils.RecordFormatType.Vyrazeno;           

            Gordic.Eko.Detail.StatusBar.updateItem(
                this.statuses!["statusBarStavStorno"]!,
                this.model.s_sto_txt!.toUpperCase(),
                stornoStatus
            ); 

            let tiskStatus = Eko.Utils.RecordFormatType.Neprecteno;

            //neproveden
            if (this.model.s_tis === 0)
                tiskStatus = Eko.Utils.RecordFormatType.Stornovano;
            //proveden
            if (this.model.s_tis === 10)
                tiskStatus = Eko.Utils.RecordFormatType.Schvaleno;       
        //} else if(this.model.s_tis == 5) {
        ////připraveno ??
        //classTisk = "";

                Gordic.Eko.Detail.StatusBar.updateItem(
                    this.statuses!["statusBarStavTisk"]!,
                    "TISK " + this.model.s_tis_txt!.toUpperCase(),
                    tiskStatus
                ); 
            
            
        }

