        private tiskDokladu(): void {


            this.findFields().gfield("model", "collect", this.model);

            const row = this.model;
            let that = this;
            let name;


            if (row.druh_dok === Hpl.Interface.DruhDokladu.danovy) {
                name = "pok_ptm_dokdan";

            }
            else if (row.druh_dok === Hpl.Interface.DruhDokladu.nedanovy) {
                name = "pok_ptm_doklad";
            }
            else if (row.druh_dok === Hpl.Interface.DruhDokladu.zjednoduseny) {
                name = "pok_ptm_dokzje";

            }

            const actVnitrniTiskDanove = GAction.createPrintAction({
                name: "actTiskDanove",
                caption: "jres:31302180", //RC 31302180 : Tisk daňových dokladů
                tema: name,
                serverParameterMethod: "Gordic.Pok.WebClient.GPokWebTisk:PokladniDoklad",
                reportStarting: function (rep) {
                    rep.customDto = { list_ixp: that.model.ixp, ixp_den: that.model.ixp_den, vyskytOpisu: that.model.s_tis == 10, settingPocetKopii: that.model.ktg_typ == Hpl.Interface.KategorieTypu.prijmovy ? that.globalSettings!.get("Pok.Nastaveni.PocKopii") : that.globalSettings!.get("Pok.Nastaveni.PocKopiiVydajovy") }
                },
                reportFinished: function (event, retVal) {

                    console.log("ReportFinish")
                    that.call("ZaznamenejTisk");
                    that.load({ Ixp: that.model.ixp });
                }
            });


            actVnitrniTiskDanove.run();
        }

