        //---------------------------------------
        //  Načtení dat z modelu do rekapitulace
        dataDoRekapitulace() {
            // this.model.c_z0 = parseDecimal(this.model.c_z0!).minus(parseDecimal(this.model.c_zx!));

            const rekapitulace: Gordic.Gin.WebClient.IGApplyRule[] = [
                //Bez daně a osvobozeno
                { from: "c_celkemOsvobozeno", to: { taxType: Gordic.Gin.WebClient.ETaxType.Osvobozeno, priceType: "baseValue" } },
                { from: "c_celkemBezDane", to: { taxType: Gordic.Gin.WebClient.ETaxType.BezDane, priceType: "baseValue" } },
                // Základní sazba daně
                { from: "c_celkemZakladZakladni", to: { taxType: Gordic.Gin.WebClient.ETaxType.Zakladni, priceType: "baseValue" } },
                { from: "c_celkemDanZakladni", to: { taxType: Gordic.Gin.WebClient.ETaxType.Zakladni, priceType: "tax" } },
                // Snížená sazba daně
                { from: "c_celkemZakladPrvniSnizena", to: { taxType: Gordic.Gin.WebClient.ETaxType.PrvniSnizena, priceType: "baseValue" } },
                { from: "c_celkemDanPrniSnizena", to: { taxType: Gordic.Gin.WebClient.ETaxType.PrvniSnizena, priceType: "tax" } },
                // Druhá snížená sazba daně
                { from: "c_celkemZakladDruhaSnizena", to: { taxType: Gordic.Gin.WebClient.ETaxType.DruhaSnizena, priceType: "baseValue" } },
                { from: "c_celkemDanDruhaSnizena", to: { taxType: Gordic.Gin.WebClient.ETaxType.DruhaSnizena, priceType: "tax" } },
                //Celkem
                { from: "c_celkem_m", to: { taxType: Gordic.Gin.WebClient.ETaxType.DokladCelkem, priceType: "sum" } },

                // ---------------
                // Zaokrouhlení
                //{ from: "c_zaokr", to: { taxType: Gordic.Eko.Prefabs.ETaxType.Zaokrouhleno, priceType: "sum" } },
            ];
            return Gordic.Gin.WebClient.Utils.dphModelApply(this.model, rekapitulace);
        }


        /**
        * closing
        */
        closing() { //funkce pro zavření detailu
            let that = this;

            const def = $.Deferred();

            const fields = this.findFields();

            //kontorla jestli jsou data změněna a jestli změny uložit
            const edit = this.findForms().gform("hasChanged");
            fields.findFields().gfield("model", "collect", this.model)

            if ((edit || that.changePorizovac)
                && (this.model.up_stav === 10 || this.model.up_stav === 15 || this.model.up_stav === 20)) { // když je něco změněno a ještě asi tyto podmínky
                //if (Editovano &&
                //    (DokladPok.Detail.UpStav != GPokDStav.schvaleno ||
                //        DokladPok.Detail.UpStav != GPokDStav.zauctovano ||
                //        DokladPok.Detail.UpStav != GPokDStav.uzavreno)



                Eko.Detail.messageBoxUnsavedData(that)
                    .on("no", function () {
                        // bez uložení
                        return def.resolve(null);
                    })
                    .on("cancel", function () {
                        // bez uložení
                        return def.reject();
                    })
                    .createDialogPromise(GDlg.mbbYes.id)
                    .then(function () {


                        that.Evidence()
                            .done(function () {

                                fields.findFields().gfield("model", "collect", that.model)
                                return def.resolve(that.model);

                            }).fail(function () { return def.reject() });
                    });

            }
            else {

                return def.resolve(this.model);
            }

            return def.promise();
        }





