            var editovatelnost = this.actionEnabled.EditovatelnyDoklad;
            var editovatelnostHlavicka = this.actionEnabled.EditovatelnaHlavickaDokladu;


            //když není hodnota nasetovaná v políčku vezmu z modelu
            const value = fields.findFields("druh_dok").gfield("getValue") ?? this.model;
            //když není hodnota nasetovaná v políčku vezmu z modelu
            const danovyPlatce = (value.druh_dok === 0 || value.druh_dok === 20) && this.actionEnabled.EkoParamsDphPlatce;
            const valueTyp = fields.findFields("ktg_typ").gfield("getValue") ?? this.model;
            //DPH datum 
            //visible
