        private validatory: ObjectLiteral<any> = {



            validacePrazdePole: {
                validate(value, source) {                                                                                           // VALIDACE
                    return !(!source.gfield("option", "disabled") &&                                                                // políčko musí být editovatelné
                        (!value || (typeof value === "string" && !value.trim()) || (typeof value === "object" && $.isEmptyObject(value)))); // nesmí být prázdné
                },
                getMessage: function (value) {                                                                                      // HLÁŠKA
                    return "Povinná hodnota";                                                                                         // RC 29750048 : Povinná hodnota
                }
            },
            validaceDruhDokladu: {
                validate(value, source) {
                    let content = $.content<Gordic.Pok.WebClient.GPokDetailDokladuTab>(source);

                    let parametr = content.pokParams.PokDokEvi;
                    let vyraz = false;

                    if (parametr == 0) {

                        vyraz = true;
                    }
                    else if (parametr == 1) {

                        if (value.ktg_typ == 1510)
                            vyraz = true;

                    }
                    else if (parametr == 2) {

                        if (value.ktg_typ == 1500)
                            vyraz = true;
                    };

                    return (!source.gfield("option", "disabled") && vyraz);

                },
                getMessage: function (value) {

                    return "Nastavení parametr neumožňuje podaní " + value.ktg_typ_txt;
                }

            }

        }
