        private prodejniCena(proCena1: Decimal, proCena2: Decimal, proCena3: Decimal): JQueryPromise<Decimal> | JQueryPromise<string> {


            var that = this;

            var def = $.Deferred();

            if (that.pokParams.PokRadPsProCe == 100) // výběr ceny
            {
                let tlacitka: GDialogButton[] = [];


                if (!proCena1.isZero()) {
                    tlacitka.push({ id: "1", text: proCena1.toString() })
                }

                if (!proCena2.isZero()) {
                    tlacitka.push({ id: "2", text: proCena2.toString() })
                }

                if (!proCena3.isZero()) {
                    tlacitka.push({ id: "3", text: proCena3.toString() })
                }

                if (tlacitka.length == 0) {
                    //GMessageBox.ShowWarning("Všechny prodejní ceny jsou nulové. Nelze uskutečnit prodej!");
                    //return false;
                    def.reject("Všechny prodejní ceny jsou nulové. Nelze uskutečnit prodej!");
                }

                if (tlacitka.length == 1) {

                    return def.resolve(new Decimal(tlacitka[0].text));
                }

                that.dialogs.messageBox("Dotaz", "Vyberte prodejní cenu", tlacitka, "fa-question-circle", 400, 250)
                    .on("close", function (ev, o, args) { // zeptám se a pokud ANO tak udělám akcu
                        if (o == "1") {

                            return def.resolve(proCena1);
                        }
                        else if (o == "2") {

                            return def.resolve(proCena2);
                        }
                        else if (o == "3") {

                            return def.resolve(proCena3);
                        } else { // asi křížek??


                            return def.reject();
                        }
                    });
            }
            else if (that.pokParams.PokRadPsProCe == 200) {
                if (!proCena1.isZero()) {
                    return def.resolve(proCena1);
                }
                else {
                    return def.reject("Prodejní cena 1 je nulová. Nelze uskutečnit prodej!");
                }
            }
            else if (that.pokParams.PokRadPsProCe == 300) {

                if (!proCena2.isZero()) {
                    return def.resolve(proCena2);
                }
                else {
                    return def.reject("Prodejní cena 2 je nulová.Nelze uskutečnit prodej!");
                }
            }
            else if (that.pokParams.PokRadPsProCe == 400) {

                if (!proCena3.isZero()) {
                    return def.resolve(proCena3);
                }
                else {
                    return def.reject("Prodejní cena 3 je nulová. Nelze uskutečnit prodej!");
                }
            }


            return def.promise();
        }


        private zkontrolujPolozkySablony(polozky: Hpl.Interface.GPokPolozkyDto[]): JQueryPromise<void> {

            var that = this;

            var def = $.Deferred();
            let counter = polozky.length;

            if (counter == 0)
                def.resolve();

            polozky.forEach(function (x) {

                counter -= 1;

                if (x.ixs_kon == null) {
                    that.showPokFlashError("Šablonu nelze uložit. Pokladní položka #" + x.radek + " nemá vyplněnou kontaci!");
                    def.reject();
                }


                if (counter === 0) {
                    def.resolve();
                }
            });

            return def.promise();



        }

