            let that = this;

            //let polozkyDto = that.gridPolozky.ggrid<Gordic.Hpl.Interface.GPokPolozkyDto>("getView").getDataRows(false);
            let polozkyDto = that.porizovac.find(".gridKontace").ggrid("getView").getDataRows(false);

