        private promiseDatumParovani(): JQueryPromise<Date> {
            var def = $.Deferred();
            var that = this;

            that.call("GetDatumParovani") // zavolám metodu pro zjištění datumu párování
                .done(function (r) {
                    if (r.stav == 0) { // stav 0 - datum bylo nalezeno tak pokračuji
                        return def.resolve(r.dat_par);
                    }
                    else if (r.stav == 1) //stav 1 - otevřu okno por výběr datumu 
                    {
                        GPokWebDialogs.VyberDataVOtevrObdobi(that.model.dat_evid!)
                            .done((date: Date) => {
                                that.dialogs.simpleForm("31302199", GPokWebDialogs.VyberDatumuDialogs(date))  //RC 31302199 : Datum párování
                                    .on("close", function (ev, data) {
                                        def.resolve(data.dat_evid);
                                    });
                            })
                            .fail(function () {
                                def.reject();
                            });

                    }
                    else if (r.stav == 2) // stav 2 - dat_par je null ale je to validní
                    {
                        def.resolve(null);
                    }

                })
                .fail(function () {
                    return def.reject();
                });

            return def.promise();
        }

