        private odstorno(): void {
            var that = this;

            this.dialogs.prompt("jres:31302215") //RC 31302215 : Zadejt důvod odstorna
                .on("ok", function (ev, duvod) { //Zeptám se na důvod
                    if (duvod && (duvod.trim() != "")) { // mám důvod
                        that.promiseDatumOdstorno() //mám datum odúčtování
                            .done(function (s) {
                                that.promiseDatumParovani() //mám datu modpárování
                                    .done(function (r) {
                                        that.promiseOdstorno(r, s, duvod, true);
                                    });
                            });
                    }
                    else { // kdyz je zavrene okno duvodu nebo je duvod null
                        that.showPokFlashError("jres:31302171"); //RC 31302171 : Je nutné uvést důvod!
                    }
                });

        }

        private promiseOdstorno(datPar: Date, datOds: Date, duvod: string, dotaz: boolean): void {

            var that = this;

            that.isl.PokDoklad.odstorno(rq => {
                return {
                    ixp: that.model.ixp,
                    datPar: datPar,
                    datOdu: datOds,
                    duvod: duvod,
                    dotaz: dotaz

                };
            }).get()
                .done(function (result) {

                    that.load({ Ixp: that.model.ixp, newPodani: false })
                        .done(function () {
                            //that.showPokFlashSuccess("Odstorno proběhlo v pořádku!");
                            that.actions.actPokOdstorno!.setPending(100);
                        })

                })
                .fail(function (xhr, type, vobj) {
                    if (type === "exception") {
                        if (vobj.baseType === "Gordic.General.GHplValidationException") {
                            vobj.handled = true;
                            that.showPokFlashError(vobj.baseMessage);

                        }
                        else if (vobj.data.member == "dotaz") {
                            vobj.handled = true;
                            return that.dialogs.confirm(vobj.baseMessage).createDialogPromise("yes").then(function () { return that.promiseOdstorno(datPar, datOds, duvod, false); });

                        }
                    }
                })
        }

