        private neaktivniFunkcnosti(): void {

            var that = this;
            //var actions = $.content(this).actions;
            var text = "";


            for (var actionName in this.actions) {

                if (!(this.actions[actionName] instanceof GAction))
                    continue;

                var action = this.actions[actionName];
                if (action != null) {
                    if (action.visible() && !action.enabled() && action.tooltip !== "") {
                        text += "<b>" + action.caption + "</b></br>"
                            + action.tooltip + "</br></br>";

                    }
                }
            }



            text += "<b>Editovtelnost hlavicka : </b></br>"
                + this.actionEnabled.EditovatelnaHlavickaDokladuToolTip + "</br></br>";

            text += "<b>Editovtelnost : </b></br>"
                + this.actionEnabled.EditovatelnyDokladToolTip + "</br></br>";


            that.dialogs.messageBox("jres:31302068", text, [GDlg.mbbOk], undefined, 600, 300); //RC 31302068 : Neaktivní funkčnosti

        }

