        private VyuctovaniZalohy(): void {

            var that = this;


            if (that.vyuctovaniZalohyPri) { // otevřeno z okna vyúčtování zálohy

                that.vyuctovaniZalohyDotaz(that.ixpZaloha, that.model.ixp);
            }
            else {

                if (that.model.ktg_dok != 100) {


                    let ixsEsu = that.element.findFields("ixs_esu").gfield("getValue");

                    if (ixsEsu != undefined)
                        ixsEsu = ixsEsu.ixs_esu;

                    //asi upravit,aby se neotvíral detail zase jako nová záložka breadcrambu,ale provedlo se na stávajícím dokladu
                    //odchytit si close a v něm předat pid Zálohy pro vyúčtování
                    var detailWindow = that.navigate("Gordic.Pok.WebClient.GPokSeznamZalohTab", { ixpNovehoDokladu: this.model.ixp, ixsEsuDokladu: ixsEsu });

                    var windowContent = $.content(detailWindow);

                    windowContent.close(function (returnData: string) {

                        if (returnData != undefined)
                            that.vyuctovaniZalohyDotaz(returnData, that.model.ixp);
                    });


                    return;

                }
                else {

                    //Dělám vyúčtování rovnou z dokladu který je záloha

                    Gordic.Pok.WebClient.GPokWebDoklad.promisePodaniDokladu(this, true, this.pokParams.GinGenIxp)
                        .done(function (ixp: string) {
                            that.vyuctovaniZalohyDotaz(that.model.ixp, ixp);

                        })
                        .fail(function (zprava: string) {

                            Gordic.Pok.WebClient.GPokFlash.showFlashWarning(that, zprava);
                        });
                }
            }
        }


        private vyuctovaniZalohyDotaz(ixpZaloha: string, ixpDokladu: string) {
            {

                var that = this;

                that.dialogs.messageBox("jres:31302301", "Jakým typem dokladu se má vyúčtování zálohy provést?", [{ text: "Příjem", id: "yes" }, { text: "Výdej", id: "no" }, { text: "Storno", id: "storno" }], "", 400, 200)
                    .on("close", function (ev, retVal) {

                        if (retVal === "yes" || retVal === "no") {

                            that.isl.PokDoklad.vyuctovaniZalohy(rq => {
                                return {
                                    kategorie: (retVal === "yes" ? 1500 : 1510),
                                    ixpNoveho: ixpDokladu,
                                    ixp: ixpZaloha

                                }
                            })
                                .get()
                                .done(function (array: string[]) {
                                    that.load({ Ixp: array[0], vyuctovaniZalohyPri: false, ixpZaloha: "", newPodani: false })
                                        .done(function (t) {
                                            that.showPokFlashSuccess("Vytvořeno vyúčtování zálohy " + ixpZaloha);

                                            that.actions.actPorizovacNew?.updatePermission({ message: "", value: true });

                                            if (array[1]) {
                                                that.showPokFlashWarning(array[1]);

                                                let ParamsJSON = { ixsVpk: that.ixsVpk, ktgTyp: (retVal === "yes" ? 1500 : 1510), ixpDen: that.model.ixp_den, uid: "'GPokVyberKontaceTab#'" };
                                                that.dialogs.showModalWindow("Gordic.Pok.WebClient.GPokVyberKontaceTab", ParamsJSON, { width: 800, height: 800 })
                                                    .on("close", function (ev, data) { // poté co se okno zavře

                                                        if (data == undefined) {
                                                        }
                                                        else {

                                                            const radek = that.porizovac.find(".gridKontace").ggrid("getView").getDataRows(false)[0];
                                                            radek.ixs_kon = data.ixs_kon;
                                                            radek.nazev = data.nazev;
                                                            radek.pokskon_nazev = data.nazev;
                                                            that.porizovac.find(".gridKontace").ggrid("getView").updateData(radek);


                                                        }

                                                    });





                                            }

                                        });

                                })
                                .fail(function (xhr, type, vobj) {
                                    if (type === "exception") {
                                        if (vobj.baseType === "Gordic.General.GHplValidationException") {
                                            vobj.handled = true;
                                            that.showPokFlashError(vobj.baseMessage);

                                        }
                                    }
                                })
                        }
                        else if (retVal === "storno") {
                            return;
                        }
                    });

            }
        }


