            var that = this;
            //var polozkyDTO = that.gridPolozky.ggrid<Gordic.Hpl.Interface.GPokPolozkyDto>("getView").getDataRows(false);
            let polozkyDto = that.porizovac.find(".gridKontace").ggrid("getView").getDataRows(false);


