        private spocitejDPH() {              
         

            let result = {
                celkemOsvobozeno: new Decimal(0),
                celkemBezDane: new Decimal(0),
                celkemZakladni: new Decimal(0),
                celkemDanZakladni: new Decimal(0),
                celkemPrvni: new Decimal(0),
                celkemDanPrvni: new Decimal(0),
                celkemDruha: new Decimal(0),
                celkemDanDruha: new Decimal(0),
            };

            if (this.porizovac.find(".gridKontace").length != 0) {

                var dataView = this.porizovac.find(".gridKontace").ggrid<Gordic.Hpl.Interface.GPokPolozkyDto>("getView").getDataRows(false);


                //kdyz neni v policku,nactu z modelu
                const jeNedanovy = (this.element.findFields("druh_dok").gfield("getValue") ?? this.model).druh_dok === 10;

                dataView.reduce((prev, curr, ind) => {
                    if (curr.priz_smaz === false && curr.id_parent === null) {
                        if (curr.dan_skup === 10) {
                            prev.celkemOsvobozeno = prev.celkemOsvobozeno.add(curr.c_celkem);
                        }
                        else if ((jeNedanovy) && (curr.dan_skup === 0)) {
                            prev.celkemBezDane = prev.celkemBezDane.add(curr.c_celkem);
                        }
                        else if (curr.dan_skup === 0) {
                            switch (curr.dan_typ) {
                                case 0://bez dph
                                    prev.celkemBezDane = prev.celkemBezDane.add(curr.c_celkem);
                                    break;
                                case 10: //základní
                                    prev.celkemZakladni = prev.celkemZakladni.add(curr.c_zak_m);
                                    prev.celkemDanZakladni = prev.celkemDanZakladni.add(curr.c_dan_m);
                                    break;
                                case 20: //snížená
                                    prev.celkemPrvni = prev.celkemPrvni.add(curr.c_zak_m);
                                    prev.celkemDanPrvni = prev.celkemDanPrvni.add(curr.c_dan_m);
                                    break;
                                case 30: //druhá snížená
                                    prev.celkemDruha = prev.celkemDruha.add(curr.c_zak_m);
                                    prev.celkemDanDruha = prev.celkemDanDruha.add(curr.c_dan_m);
                                    break;
                            }
                        }
                    }
                    return prev;
                }, result)

            }

            const baseValueCelkem = result.celkemBezDane.add(result.celkemOsvobozeno).add(result.celkemZakladni).add(result.celkemPrvni).add(result.celkemDruha);
            const taxCelkem = result.celkemDanZakladni.add(result.celkemDanPrvni).add(result.celkemDanDruha);
            const sumZakladni = result.celkemZakladni.add(result.celkemDanZakladni);
            const sumPrvni = result.celkemPrvni.add(result.celkemDanPrvni);
            const sumDruha = result.celkemDruha.add(result.celkemDanDruha);
            const sumCelkem = result.celkemBezDane.add(result.celkemOsvobozeno).add(sumZakladni).add(sumPrvni).add(sumDruha);
            const prices: Gordic.Gin.WebClient.IGRecapPricesMap = {
                [Gordic.Gin.WebClient.ETaxType.BezDaneNum]: { baseValue: result.celkemBezDane, sum: result.celkemBezDane },
                [Gordic.Gin.WebClient.ETaxType.OsvobozenoNum]: { baseValue: result.celkemOsvobozeno, sum: result.celkemOsvobozeno },
                [Gordic.Gin.WebClient.ETaxType.ZakladniNum]: { baseValue: result.celkemZakladni, tax: result.celkemDanZakladni, sum: sumZakladni },
                [Gordic.Gin.WebClient.ETaxType.PrvniSnizenaNum]: { baseValue: result.celkemPrvni, tax: result.celkemDanPrvni, sum: sumPrvni },
                [Gordic.Gin.WebClient.ETaxType.DruhaSnizenaNum]: { baseValue: result.celkemDruha, tax: result.celkemDanDruha, sum: sumDruha },
                [Gordic.Gin.WebClient.ETaxType.DokladCelkemNum]: { baseValue: baseValueCelkem, tax: taxCelkem, sum: sumCelkem },
            }


            return prices;
        }


